// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Creator deposits 1 wei
        address creator = address(this);
        vm.deal(creator, 1 ether);
        vm.prank(creator);
        c.deposit{value: 1 wei}();

        // Creator calls migrateTo(creator)
        vm.prank(creator);
        c.migrateTo(creator);

        // Now try to call deposit again — reference should succeed, buggy contract should revert
        bool ok;
        vm.deal(creator, 1 ether);
        vm.prank(creator);
        try c.deposit{value: 1 wei}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "Deposit should succeed after migrateTo in reference");
    }
}

