pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: creator is the deployer
        address creator = address(this);

        // Creator deposits 1 wei
        vm.deal(creator, 1 wei);
        vm.prank(creator);
        c.deposit{value: 1 wei}();

        // Creator calls migrateTo(creator)
        vm.prank(creator);
        c.migrateTo(creator);

        // Now try a deposit by a different user
        address user = address(0x1234);
        vm.deal(user, 1 wei);
        vm.prank(user);

        bool ok;
        try c.deposit{value: 1 wei}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: contract still alive, deposit succeeds (ok == true)
        // Buggy: contract selfdestructed, deposit reverts (ok == false)
        assertTrue(ok, "Deposit after migrateTo should succeed in reference");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract via deposit
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.deposit{value: 1 ether}();
        // Call migrateTo with the contract's own address (but the reference sends to 'to')
        c.migrateTo(address(this));
        // After migrateTo, reference sends all balance to address(this) (which is test contract), so c.balance = 0
        // Buggy version sends to address(this) (itself), so c.balance remains 1 ether
        assertTrue(address(c).balance == 0);
    }
}

